const data = $input.item.json;

function toE164(phone) {
  if (!phone) return '';
  let digits = String(phone).replace(/\D/g, '');
  if (digits.startsWith('0') && digits.length === 11) {
    digits = '234' + digits.slice(1);
  } else if (digits.startsWith('234') && digits.length === 13) {
    // already 234
  }
  return 'whatsapp:+' + digits;
}

const revenue = Number(data.revenue_today || 0);
const formattedRevenue = '₦' + revenue.toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const dateStr = data.formatted_date || data.date || 'Yesterday';
const checkins = data.checkins_today || 0;
const uniqueCheckins = data.unique_checkins_today || 0;
const newMembers = data.new_members_today || 0;
const expiring = data.expiring_today || 0;

const rawOwnerPhone = $vars.OWNER_WHATSAPP_NUMBER || '+2348012345678';
const ownerPhone = toE164(rawOwnerPhone);

let activityNote = 'Great workout momentum across all shifts!';
if (checkins === 0 && revenue === 0) {
  activityNote = 'Rest day / Gym closed (0 check-ins recorded).';
}

const messageBody = `📊 *ABUJA GYM — EXECUTIVE DAILY REPORT*\n` +
  `📅 *Date:* ${dateStr} (Full 24h Wrap-up)\n` +
  `──────────────────────────\n` +
  `💰 *Revenue Collected:* ${formattedRevenue}\n` +
  `🏋️ *Total Check-ins:* ${checkins} workouts (${uniqueCheckins} unique athletes)\n` +
  `✨ *New Members Enrolled:* ${newMembers}\n` +
  `⚠️ *Subscriptions Expired:* ${expiring}\n` +
  `──────────────────────────\n` +
  `💡 ${activityNote}\n\n` +
  `Have a productive day ahead at the gym! 💪`;

return {
  json: {
    owner_phone: ownerPhone,
    date: dateStr,
    revenue: formattedRevenue,
    checkins: checkins,
    unique_checkins: uniqueCheckins,
    new_members: newMembers,
    expiring: expiring,
    message_body: messageBody
  }
};
